fn sz? bsearch(int[] arr, int x)
{
    sz i;
    sz j = arr.len - 1;
    while (i <= j)
    {
        sz k = i + ((j - i) / 2);
        switch
        {
            case arr[k] == x: return k;
            case arr[k] < x: i = k + 1;
            default: j = k - 1;
        }
    }
    return NOT_FOUND~;
}

fn sz? bsearch_r(int[] arr, int x, sz i, sz j)
{
    if (j < i) return NOT_FOUND~;

    sz k = i + ((j - i) / 2);

    switch
    {
        case arr[k] == x: return k;
        case arr[k] < x: return bsearch_r(arr, x, k + 1, j)!;
        default:
            return bsearch_r(arr, x, i, k - 1)!;
    }
}

