BEGIN
  WriteInt(X, 1);
  IF IndX >= 0 THEN
    WriteString(" is at index ");
    WriteInt(IndX, 1);
    WriteString(".")
  ELSE
    WriteString(" is not found.")
  END;
  WriteLn
END WriteResult;

BEGIN
  X := 2;
  WriteResult(X, DoBinarySearch(A, X));
  X := 5;
  WriteResult(X, DoBinarySearchRec(A, X, 0, HIGH(A)));
END BinarySearch.

