fn binary_search_iterative(arr: int*, value: int, low: int, high: int) -> int {
    let l = low;
    let h = high;

    while l <= h {
        let mid = l + (h - l) / 2;

        if arr[mid] > value {
            h = mid - 1;
        } else if arr[mid] < value {
            l = mid + 1;
        } else {
            return mid;
        }
    }
    return -1;
}

